window.__finlexDocLoaded(10167,{"id":10167,"articles":[{"id":1000699,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Mandates two-way communication between the independent auditor and the audit committee regarding audit strategy, significant risks, critical accounting policies and estimates, uncorrected misstatements, and auditor independence.","seq":0},{"id":1000700,"no":"AS 1301.04–.26","heading":"Audit Strategy, Critical Estimates & Pre-Report Communications","text":"• Mandatory Topics: Terms of engagement, overall audit strategy & significant risks, critical accounting policies/practices, critical accounting estimates, significant unusual transactions, uncorrected/corrected misstatements, and disagreements with management.\n• Timing (AS 1301.26): All required communications must occur PRIOR to the issuance of the auditor's report (directly linking to CAM identification under AS 3101).","seq":1},{"id":1000701,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Parallel to ISA 260 (Revised), with direct statutory tie-in to SOX Section 204 and AS 3101 Critical Audit Matters (only matters communicated or required to be communicated to the audit committee can be CAMs).","seq":2},{"id":1000702,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (PCAOB Auditing Standards): https://pcaobus.org/oversight/standards/auditing-standards\nStatus: in_force.","seq":3}]});
